import { buildClientCoreScript } from './visual-render-client.mjs'
import { buildClientDiagramsScript } from './visual-render-client-diagrams.mjs'
import {
  MAX_PROTOTYPE_SRCDOC_BYTES,
  renderBlueprintLandingHtml,
  renderCommandPaletteHtml,
  renderDialogsHtml,
  renderInspectorShellHtml,
  renderPrototypeSlot,
  renderPrototypeSwitcher,
} from './visual-render-panels.mjs'
